mapper.insert:
INSERT INTO CHB_INVEST_TRADE ( TRADE_SEQNO, TRADE_CODE, PROD_ID, REGIST_BANK_CODE, ASSET_CODE, CCY, AMT, CNY_AMT, CUR_ASSET_TYPE, CUR_ASSETDET_TYPE, DEALDATE, TRADE_COUNTER, UNIT_PRICE_FULL, UNIT_PRICE_NET, END_RATE, CONTRACT_CODE, REMARK, STATUS, DEPT_CODE, CREATE_USER, CREATE_TIME, UPDATE_USER, UPDATE_TIME, DATA_SOURCE, NUM, ASSET_METHOD, RIVAL_PARTY_TYPE, INVEST_APPROVER_ID, INVEST_APPROVER_NAME, INVEST_TRADER_ID, INVEST_TRADER_NAME, ERR_MSG ) select * from ( select TEMP.* from (
SELECT #{item.tradeSeqno,jdbcType=VARCHAR} TRADE_SEQNO, #{item.tradeCode,jdbcType=VARCHAR} TRADE_CODE, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.amt,jdbcType=NUMERIC} AMT, #{item.cnyAmt,jdbcType=NUMERIC} CNY_AMT, #{item.curAssetType,jdbcType=VARCHAR} CUR_ASSET_TYPE, #{item.curAssetdetType,jdbcType=VARCHAR} CUR_ASSETDET_TYPE, #{item.dealdate,jdbcType=DATE} DEALDATE, #{item.tradeCounter,jdbcType=VARCHAR} TRADE_COUNTER, #{item.unitPriceFull,jdbcType=NUMERIC} UNIT_PRICE_FULL, #{item.unitPriceNet,jdbcType=NUMERIC} UNIT_PRICE_NET, #{item.endRate,jdbcType=NUMERIC} END_RATE, #{item.contractCode,jdbcType=VARCHAR} CONTRACT_CODE, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.status,jdbcType=VARCHAR} STATUS, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.num,jdbcType=NUMERIC} NUM, #{item.assetMethod,jdbcType=VARCHAR} ASSET_METHOD, #{item.rivalPartyType,jdbcType=VARCHAR} RIVAL_PARTY_TYPE, #{item.investApproverId,jdbcType=VARCHAR} INVEST_APPROVER_ID, #{item.investApproverName,jdbcType=VARCHAR} INVEST_APPROVER_NAME, #{item.investTraderId,jdbcType=VARCHAR} INVEST_TRADER_ID, #{item.investTraderName,jdbcType=VARCHAR} INVEST_TRADER_NAME, #{item.errMsg,jdbcType=VARCHAR} ERR_MSG FROM DUAL
) TEMP where not exists (SELECT 1 FROM CHB_INVEST_TRADE a where a.TRADE_CODE = TEMP.TRADE_CODE AND a.PROD_ID = TEMP.PROD_ID AND a.ASSET_CODE = TEMP.ASSET_CODE ) )a;
UPDATE CHB_INVEST_TRADE a,( select * from ( select TEMP.* from ( SELECT #{ item.tradeSeqno,jdbcType=VARCHAR} TRADE_SEQNO, #{item.tradeCode,jdbcType=VARCHAR} TRADE_CODE, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.amt,jdbcType=NUMERIC} AMT, #{item.cnyAmt,jdbcType=NUMERIC} CNY_AMT, #{item.curAssetType,jdbcType=VARCHAR} CUR_ASSET_TYPE, #{item.curAssetdetType,jdbcType=VARCHAR} CUR_ASSETDET_TYPE, #{item.dealdate,jdbcType=DATE} DEALDATE, #{item.tradeCounter,jdbcType=VARCHAR} TRADE_COUNTER, #{item.unitPriceFull,jdbcType=NUMERIC} UNIT_PRICE_FULL, #{item.unitPriceNet,jdbcType=NUMERIC} UNIT_PRICE_NET, #{item.endRate,jdbcType=NUMERIC} END_RATE, #{item.contractCode,jdbcType=VARCHAR} CONTRACT_CODE, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.status,jdbcType=VARCHAR} STATUS, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.num,jdbcType=NUMERIC} NUM, #{item.assetMethod,jdbcType=VARCHAR} ASSET_METHOD, #{item.rivalPartyType,jdbcType=VARCHAR} RIVAL_PARTY_TYPE, #{item.investApproverId,jdbcType=VARCHAR} INVEST_APPROVER_ID, #{item.investApproverName,jdbcType=VARCHAR} INVEST_APPROVER_NAME, #{item.investTraderId,jdbcType=VARCHAR} INVEST_TRADER_ID, #{item.investTraderName,jdbcType=VARCHAR} INVEST_TRADER_NAME, #{item.errMsg,jdbcType=VARCHAR} ERR_MSG FROM DUAL )TEMP ) a ) b SET a.REGIST_BANK_CODE = b.REGIST_BANK_CODE, a.CCY = b.CCY, a.AMT = b.AMT, a.CNY_AMT = b.CNY_AMT, a.CUR_ASSET_TYPE = b.CUR_ASSET_TYPE, a.CUR_ASSETDET_TYPE = b.CUR_ASSETDET_TYPE, a.DEALDATE = b.DEALDATE, a.TRADE_COUNTER = b.TRADE_COUNTER, a.UNIT_PRICE_FULL = b.UNIT_PRICE_FULL, a.UNIT_PRICE_NET = b.UNIT_PRICE_NET, a.END_RATE = b.END_RATE, a.CONTRACT_CODE = b.CONTRACT_CODE, a.REMARK = b.REMARK, a.UPDATE_USER = b.UPDATE_USER, a.UPDATE_TIME = b.UPDATE_TIME, a.DATA_SOURCE = b.DATA_SOURCE, a.NUM = b.NUM, a.ASSET_METHOD = b.ASSET_METHOD, a.RIVAL_PARTY_TYPE = b.RIVAL_PARTY_TYPE, a.INVEST_APPROVER_ID = b.INVEST_APPROVER_ID, a.INVEST_APPROVER_NAME = b.INVEST_APPROVER_NAME, a.INVEST_TRADER_ID = b.INVEST_TRADER_ID, a.INVEST_TRADER_NAME = b.INVEST_TRADER_NAME, a.ERR_MSG = b.ERR_MSG where a.TRADE_CODE = b.TRADE_CODE AND a.PROD_ID = b.PROD_ID AND a.ASSET_CODE = b.ASSET_CODE

