#{item}
union all select a.DATAUUID TRADE_SEQNO, a.TRADE_CODE, a.PROD_ID, null REGIST_BANK_CODE, a.ASSET_CODE, null CCY, null AMT, null CNY_AMT, null CUR_ASSET_TYPE, null CUR_ASSETDET_TYPE, a.DEALDATE, a.TRADE_COUNTER, null UNIT_PRICE_FULL, null UNIT_PRICE_NET, null END_RATE, null CONTRACT_CODE, null REMARK, a.STATUS, a.DEPT_CODE, a.CREATE_USER, a.CREATE_TIME, a.UPDATE_USER, a.UPDATE_TIME, null DATA_SOURCE, null NUM, null ASSET_METHOD, null RIVAL_PARTY_TYPE, null INVEST_APPROVER_ID, null INVEST_APPROVER_NAME, null INVEST_TRADER_ID, null INVEST_TRADER_NAME, a.ERR_MSG errMsg, a.ORG_DATA orgData, b.REG_CODE regCode, c.ASSET_NAME assetName from chb_invest_trade_errodata a LEFT JOIN CHB_PRD_BASEINFO b ON a.PROD_ID = b.PROD_ID LEFT JOIN CHB_ASSET_INFO c ON a.ASSET_CODE = c.ASSET_CODE where a.DATAUUID in
